// static
bool StructTraits<::chrome_cart::mojom::MerchantCart::DataView, ::chrome_cart::mojom::MerchantCartPtr>::Read(
    ::chrome_cart::mojom::MerchantCart::DataView input,
    ::chrome_cart::mojom::MerchantCartPtr* output) {
  bool success = true;
  ::chrome_cart::mojom::MerchantCartPtr result(::chrome_cart::mojom::MerchantCart::New());
  
      if (success && !input.ReadMerchant(&result->merchant))
        success = false;
      if (success && !input.ReadCartUrl(&result->cart_url))
        success = false;
      if (success && !input.ReadProductImageUrls(&result->product_image_urls))
        success = false;
      if (success && !input.ReadDiscountText(&result->discount_text))
        success = false;
  *output = std::move(result);
  return success;
}

